const previousItems = $json.items || [];

const sources = [
  { url: 'https://www.ceps.eu/feed/', name: 'CEPS' },
  { url: 'https://www.bruegel.org/feed', name: 'Bruegel' },
  { url: 'https://oecd.ai/en/feed', name: 'OECD AI' },
  { url: 'https://news.google.com/rss/search?q=sovereign+AI+Europe+treaty&hl=en-US&gl=US&ceid=US:en', name: 'Google News: Sovereign AI Europe' },
  { url: 'https://news.google.com/rss/search?q=%22CERN+for+AI%22+OR+%22European+AGI%22+OR+%22AI+treaty%22+Europe&hl=en-US&gl=US&ceid=US:en', name: 'Google News: CERN for AI' }
];

const feeds = [];
for (const source of sources) {
  try {
    const body = await this.helpers.httpRequest({
      method: 'GET',
      url: source.url,
      encoding: 'utf-8',
    });
    const xml = typeof body === 'string' ? body : JSON.stringify(body);
    feeds.push({ name: source.name, xml });
  } catch(e) {
    console.log('Skipped source: ' + source.name + ' — ' + e.message);
  }
}

return [{ json: { feeds, previousItems } }];

const { feeds, previousItems } = $json;
const fourteenDaysAgo = new Date(Date.now() - 14 * 24 * 60 * 60 * 1000);

function extractTag(xml, tag) {
  // Handle CDATA
  const cdataRe = new RegExp('<' + tag + '>\\s*<!\\[CDATA\\[([\\s\\S]*?)\\]\\]>\\s*</' + tag + '>', 'i');
  const cdataMatch = xml.match(cdataRe);
  if (cdataMatch) return cdataMatch[1].trim();

  // Handle plain text
  const plainRe = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>', 'i');
  const plainMatch = xml.match(plainRe);
  if (plainMatch) return plainMatch[1].replace(/<[^>]*>/g, '').trim();

  return '';
}

const allItems = [];

for (const feed of feeds) {
  const { xml, name } = feed;
  const itemMatches = xml.match(/<item>[\s\S]*?<\/item>/g) || [];

  for (const itemXml of itemMatches) {
    const title = extractTag(itemXml, 'title');
    const link = extractTag(itemXml, 'link') || (itemXml.match(/href=\"([^\"]+)\"/) || [])[1] || '';
    const pubDate = extractTag(itemXml, 'pubDate');
    const description = extractTag(itemXml, 'description').substring(0, 400);

    if (!title || !link) continue;

    const itemDate = pubDate ? new Date(pubDate) : new Date();
    if (isNaN(itemDate.getTime()) || itemDate < fourteenDaysAgo) continue;

    allItems.push({ title, link, pubDate: itemDate.toISOString(), description, source: name });
  }
}

// Deduplicate by URL
const seen = new Set();
const unique = allItems.filter(item => {
  if (seen.has(item.link)) return false;
  seen.add(item.link);
  return true;
});

// Sort newest first, cap at 30 for Claude input
unique.sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));
const items = unique.slice(0, 30);

return [{ json: { items, count: items.length, previousItems } }];

const { items, previousItems } = $json;

const apiKey = "ANTHROPIC_API_KEY_HERE";

const systemPrompt = 'You are a policy analyst for Europa Nova, a proposed treaty-based European institution for sovereign AGI development. Your task is to filter and annotate recent news items for relevance to European AI policy and sovereignty.

Relevant topics:
- European sovereign AI capability and strategic autonomy
- AI compute infrastructure, data centres, Nordic energy for AI
- Frontier model development, AI safety, governance frameworks
- EU AI policy (AI Factories, Gigafactories, AI Act, AI Continent Action Plan)
- Geopolitical AI competition: US-Europe-China dynamics
- Treaty-based international technology cooperation (CERN, ESA, Galileo precedents)
- Sovereign wealth fund investment in technology
- AI talent, brain drain, research institutions
- Norway, Sweden, Finland AI policy and energy infrastructure

For each relevant item, write a commentary of exactly 3-4 sentences. The commentary must:
- State what happened and why it matters for European AI sovereignty specifically
- Be analytical and forward-looking, not journalistic
- Stay within the bounds of what the source material supports — do not overstate
- Avoid buzzwords: no synergy, paradigm shift, game-changing, crucial, holistic
- Never start with I or This
- End with a forward-looking observation or implication

Respond ONLY with valid JSON in this exact format — no preamble, no markdown fences:
{
  "items": [
    {
      "date": "YYYY-MM-DD",
      "source": "Source name",
      "title": "Article title",
      "url": "Article URL",
      "commentary": "3-4 sentence commentary here"
    }
  ]
}

Include maximum 5 most relevant items. If fewer than 5 are relevant, include only those. If nothing is relevant, return {"items": []}.';

const itemList = items.map(function(item, i) {
  return (i + 1) + ". TITLE: " + item.title + "
SOURCE: " + item.source + "
DATE: " + item.pubDate + "
URL: " + item.link + "
SUMMARY: " + item.description;
}).join("

");

const userPrompt = "Here are " + items.length + " recent news items. Filter for relevance and write analytical commentary for each relevant item:

" + itemList;

const response = await this.helpers.httpRequest({
  method: "POST",
  url: "https://api.anthropic.com/v1/messages",
  headers: {
    "anthropic-version": "2023-06-01",
    "content-type": "application/json",
    "x-api-key": apiKey
  },
  body: {
    model: "claude-sonnet-4-20250514",
    max_tokens: 2000,
    system: systemPrompt,
    messages: [{ role: "user", content: userPrompt }]
  },
  json: true,
  timeout: 120000
});

return [{ json: { ...response, previousItems } }];

const claudeResponse = $input.first().json;
const previousItems = $('Prep Claude').first().json.previousItems || [];

// Extract text from Claude response
const content = claudeResponse.content || [];
const textBlock = content.find(b => b.type === 'text');
const text = textBlock?.text || '{"items":[]}';

// Parse Claude's JSON output
let parsed;
try {
  const clean = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  console.log('JSON parse error: ' + e.message);
  console.log('Raw text: ' + text.substring(0, 500));
  parsed = { items: [] };
}

let newItems = (parsed.items || []).slice(0, 5);

// Fallback: if Claude returned 0 items, keep previous items
if (newItems.length === 0 && previousItems.length > 0) {
  console.log('No new items from Claude — retaining previous items as fallback');
  newItems = previousItems.slice(0, 5);
}

// Deduplicate: merge new + previous, prefer new, cap at 5
if (newItems.length > 0 && newItems.length < 5 && previousItems.length > 0) {
  const newUrls = new Set(newItems.map(i => i.url));
  const filler = previousItems.filter(i => !newUrls.has(i.url));
  newItems = newItems.concat(filler).slice(0, 5);
}

const newsData = {
  updated: new Date().toISOString(),
  items: newItems
};

return [{ json: { newsData, count: newItems.length } }];

const newsData = $json.newsData;
const jsonString = JSON.stringify(newsData, null, 2);
const base64 = Buffer.from(jsonString, 'utf8').toString('base64');

return [{
  json: {},
  binary: {
    data: {
      data: base64,
      mimeType: 'application/json',
      fileName: 'news.json',
      fileExtension: 'json'
    }
  }
}];

// Push news.json to GitHub Pages repo via GitHub Contents API
// Requires a GitHub Personal Access Token with repo scope
const githubToken = "GITHUB_TOKEN_HERE";
const owner = "thorhalvorsen";
const repo = "europa-nova";
const path = "news.json";
const branch = "main";

// Get the binary data from previous node
const binaryData = $input.first().binary.data;
const content = binaryData.data; // Already base64 encoded

// Get current file SHA (required for updates)
let sha = '';
try {
  const existing = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + path + '?ref=' + branch,
    headers: {
      'Authorization': 'Bearer ' + githubToken,
      'Accept': 'application/vnd.github.v3+json',
      'User-Agent': 'n8n-europa-nova'
    },
    json: true
  });
  sha = existing.sha;
} catch(e) {
  console.log('File does not exist yet, creating new');
}

// Commit the file
const commitBody = {
  message: 'Update news.json via n8n workflow',
  content: content,
  branch: branch
};
if (sha) commitBody.sha = sha;

const result = await this.helpers.httpRequest({
  method: 'PUT',
  url: 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + path,
  headers: {
    'Authorization': 'Bearer ' + githubToken,
    'Accept': 'application/vnd.github.v3+json',
    'User-Agent': 'n8n-europa-nova',
    'Content-Type': 'application/json'
  },
  body: commitBody,
  json: true
});

return [{ json: { success: true, commitSha: result.commit?.sha, url: result.content?.html_url } }];

// Error handler: if Claude API fails, retain previous items
const previousItems = $('Prep Claude').first().json.previousItems || [];

if (previousItems.length === 0) {
  console.log('Claude API failed and no previous items available — skipping update');
  return [];
}

console.log('Claude API failed — retaining previous ' + previousItems.length + ' items');

const newsData = {
  updated: new Date().toISOString(),
  items: previousItems.slice(0, 5)
};

return [{ json: { newsData, count: previousItems.length } }];
